/// Market Model.
#[repr(u8)]
#[derive(Debug, Copy, Clone, Eq, PartialEq, Serialize, Deserialize)]
pub enum MarketModelType {
  /// A Central Limit Order Book (CLOB)
  CLOB = 0x0001,
  /// BLOCK
  BLOCK = 0x0002,
  /// HYBRID market model
  HYBRID = 0x0003,
  /// CROSS
  CROSS = 0x0004,
  /// Not applicable
  NotApplicable = 0x0005,
}
impl Default for MarketModelType {
  fn default() -> Self {
    Self::CLOB
  }
}
impl std::convert::TryFrom<u8> for MarketModelType {
  type Error = InvalidVariant;
  fn try_from(value: u8) -> Result<Self, Self::Error> {
    match value {
      0x0001 => Ok(Self::CLOB),
      0x0002 => Ok(Self::BLOCK),
      0x0003 => Ok(Self::HYBRID),
      0x0004 => Ok(Self::CROSS),
      0x0005 => Ok(Self::NotApplicable),
      other => Err(InvalidVariant::new(other as u32, "MarketModelType")),
    }
  }
}

/// Test scenario name
pub type ScenarioName = [AnsiChar; 200];


/// Test event type
#[repr(u8)]
#[derive(Debug, Copy, Clone, Eq, PartialEq, Serialize, Deserialize)]
pub enum EventType {
  /// Flush the test scenario
  Flush = 0x0001,
  /// Start of test scenario
  ScenarioStart = 0x0002,
  /// End of test scenario
  ScenarioEnd = 0x0003,
}
impl Default for EventType {
  fn default() -> Self {
    Self::Flush
  }
}
impl std::convert::TryFrom<u8> for EventType {
  type Error = InvalidVariant;
  fn try_from(value: u8) -> Result<Self, Self::Error> {
    match value {
      0x0001 => Ok(Self::Flush),
      0x0002 => Ok(Self::ScenarioStart),
      0x0003 => Ok(Self::ScenarioEnd),
      other => Err(InvalidVariant::new(other as u32, "EventType")),
    }
  }
}

